(()=>{
 'use strict';const P=window.ObservationPhysics,C=window.ObservationContent,$=id=>document.getElementById(id),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 const defaults={photo:{distance:40,absolute:-20,size:3},spectral:{redshift:.1,dispersion:100,zoom:false},profile:{n:4,re:3,aperture:1,compare:false},survey:{limit:17,mode:'flux',distance:60},evidence:0};
 const state=JSON.parse(JSON.stringify(defaults));
 const ranges={photo:{distance:[10,100],absolute:[-23,-16],size:[1,5]},spectral:{redshift:[0,.5],dispersion:[20,350]},profile:{n:[1,6],re:[1,6],aperture:[.2,5]},survey:{limit:[14,20],distance:[20,100]}};
 try{const old=JSON.parse(localStorage.getItem('galaxies-chapter-2-labs')||'null');if(old){for(const[group,keys]of Object.entries(ranges))for(const[k,[a,b]]of Object.entries(keys))if(Number.isFinite(old[group]?.[k]))state[group][k]=clamp(old[group][k],a,b);state.profile.n=Math.round(state.profile.n);state.spectral.zoom=old.spectral?.zoom===true;state.profile.compare=old.profile?.compare===true;state.survey.mode=old.survey?.mode==='volume'?'volume':'flux';if(Number.isInteger(old.evidence))state.evidence=clamp(old.evidence,0,C.evidence.length-1);}}catch{}
 function save(){try{localStorage.setItem('galaxies-chapter-2-labs',JSON.stringify(state));}catch{}}
 const players={photo:{active:false,last:0},spectral:{active:false,last:0}};
 function stop(which){players[which].active=false;players[which].last=0;if(which==='photo'){$('photo-play').textContent=state.photo.distance>=100?'重播远离过程':'演示逐渐远离';$('photo-takeaway').setAttribute('aria-live','polite');}else $('spectrum-play').textContent=state.spectral.redshift>=.5?'重播红移变化':'播放红移变化';}
 function stopAll(){stop('photo');stop('spectral');save();}
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAll();});
 function photoPrompt(){const v=P.photometry(state.photo.absolute,state.photo.distance,state.photo.size);return `我在学习 MBW §2.1.1 pp.26–29。理想欧氏模型，无消光、无噪声、已分辨指数盘：M=${state.photo.absolute}，距离=${state.photo.distance.toFixed(2)} Mpc，半光半径=${state.photo.size} kpc；算得 m=${v.m.toFixed(3)}，半光角半径=${v.theta.toFixed(3)} arcsec，半光区平均面亮度=${v.meanMu.toFixed(3)} mag/arcsec²。请从通量和角面积解释为什么距离改变而面亮度不变，以及这一结论为何不能直接用于高红移或未分辨源。`;}
 function tutor(prompt){stopAll();window.showTutor(prompt);}
 $('photo-question').addEventListener('click',()=>tutor(photoPrompt()));$('tutor-open').addEventListener('click',()=>tutor(photoPrompt()));
 function canvasSetup(canvas){const {width,height}=canvas.getBoundingClientRect();const ratio=Math.min(2,devicePixelRatio||1);canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);const context=canvas.getContext('2d');context.setTransform(ratio,0,0,ratio,0,0);return {context,width,height,ratio};}
 // An analytic face-on image with one fixed intensity mapping, shared by both distances.
 function drawPhoto(canvas,d){const {context:ctx,width:w,height:h}=canvasSetup(canvas);if(!w)return;const sample=document.createElement('canvas'),sw=Math.min(420,Math.round(w)),sh=Math.round(h*sw/w);sample.width=sw;sample.height=sh;const sc=sample.getContext('2d'),pixels=sc.createImageData(sw,sh),p=state.photo,pcScale=d*1000*240/P.ARCSEC/sw,L=10**(-.4*(p.absolute+20));
  for(let y=0;y<sh;y++)for(let x=0;x<sw;x++){const r=Math.hypot(x-sw/2,y-sh*.53)*pcScale,I=P.surfaceDensity(r,1,p.size)*L,t=1-Math.exp(-Math.pow(I*80,.7)),k=(y*sw+x)*4;pixels.data[k]=7+238*t;pixels.data[k+1]=15+216*t;pixels.data[k+2]=24+180*t;pixels.data[k+3]=255;}sc.putImageData(pixels,0,0);ctx.drawImage(sample,0,0,w,h);const theta=P.photometry(p.absolute,d,p.size).theta,r=theta/240*w;ctx.beginPath();ctx.arc(w/2,h*.53,r,0,Math.PI*2);ctx.strokeStyle=window.BookTheme.color('#e4c38975');ctx.setLineDash([3,5]);ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);const len=30/240*w;ctx.strokeStyle=window.BookTheme.color('#819b9e');ctx.beginPath();ctx.moveTo(w-15-len,h-32);ctx.lineTo(w-15,h-32);ctx.stroke();ctx.fillStyle=window.BookTheme.color('#98aeae');ctx.font='10px -apple-system, sans-serif';ctx.textAlign='right';ctx.fillText('30″',w-15,h-38);}
 function updatePhoto(){const p=state.photo,v=P.photometry(p.absolute,p.distance,p.size);for(const[k,id]of Object.entries({distance:'photo-distance',absolute:'photo-absolute',size:'photo-size'}))$(id).value=p[k];$('distance-value').textContent=p.distance.toFixed(0)+' Mpc';$('absolute-value').textContent=p.absolute.toFixed(1)+' mag';$('size-value').textContent=p.size.toFixed(1)+' kpc';$('photo-distance-label').textContent=p.distance.toFixed(0)+' Mpc';$('photo-m').textContent=v.m.toFixed(2);$('photo-flux').textContent=v.fluxRatio.toFixed(3);$('photo-angle').textContent=v.theta.toFixed(1)+'″';$('photo-mu').textContent=v.meanMu.toFixed(2);$('photo-takeaway').textContent=`当前通量是 20 Mpc 时的 ${v.fluxRatio.toFixed(3)} 倍，半光角半径是其 ${(20/p.distance).toFixed(2)} 倍。两幅图的物理星系相同，虚线圈均标记半光半径；平均面亮度为 ${v.meanMu.toFixed(2)} mag/arcsec²。`;drawPhoto($('photo-reference'),20);drawPhoto($('photo-current'),p.distance);}
 for(const[k,id]of Object.entries({distance:'photo-distance',absolute:'photo-absolute',size:'photo-size'})){$(id).addEventListener('input',e=>{stop('photo');state.photo[k]=+e.target.value;updatePhoto();});$(id).addEventListener('change',save);}
 $('photo-play').addEventListener('click',()=>{if(players.photo.active){stop('photo');save();return;}if(state.photo.distance>=100)state.photo.distance=10;players.photo.active=true;players.photo.last=0;$('photo-play').textContent='暂停';$('photo-takeaway').setAttribute('aria-live','off');requestAnimationFrame(photoTick);});
 function photoTick(t){const p=players.photo;if(!p.active)return;if(!p.last)p.last=t;const dt=t-p.last;if(dt>=50){state.photo.distance=Math.min(100,state.photo.distance+Math.min(dt,100)*.01125);p.last=t;updatePhoto();}if(state.photo.distance>=100){stop('photo');save();}else requestAnimationFrame(photoTick);}

 function chartFrame(id,m={left:54,right:18,top:25,bottom:48}){const node=$(id),rect=node.getBoundingClientRect(),w=rect.width,h=rect.height,svg=d3.select(node);svg.selectAll('*').remove();svg.attr('viewBox',`0 0 ${w} ${h}`);return {svg,node,w,h,m};}
 function axes(f,x,y,xlabel,ylabel,{log=false}={}){const p=window.BookCharts.frame(f.node,{x,y,xLabel:xlabel,yLabel:ylabel});Object.assign(f.m,p.m);}
 function updateSpectrum(){const s=state.spectral;for(const k of ['redshift','dispersion'])$(k).value=s[k];$('redshift-value').textContent=s.redshift.toFixed(3);$('dispersion-value').textContent=s.dispersion.toFixed(0)+' km/s';$('spectrum-zoom').textContent=s.zoom?'返回完整光谱':'放大 Hα 谱线';$('spectrum-zoom').setAttribute('aria-pressed',String(s.zoom));const lines=P.lines.map(l=>P.spectralLine(l,s.redshift,s.dispersion)),ha=lines[2],f=chartFrame('spectrum-chart'),{svg,w,h,m}=f;const domain=s.zoom?[ha.center-8,ha.center+8]:[450,1000],x=d3.scaleLinear().domain(domain).range([m.left,w-m.right]);let samples=Array.from({length:501},(_,i)=>domain[0]+(domain[1]-domain[0])*i/500);for(const l of lines)for(let j=-40;j<=40;j++)samples.push(l.center+j*l.width/8);samples=samples.filter(v=>v>=domain[0]&&v<=domain[1]).sort((a,b)=>a-b);const data=samples.map(lambda=>({lambda,flux:P.spectrumAt(lambda,s.redshift,s.dispersion)}));const y=d3.scaleLinear().domain([0,Math.max(2.8,d3.max(data,d=>d.flux)*1.08)]).range([h-m.bottom,m.top]);axes(f,x,y,'观测波长 / nm','归一化谱密度');svg.append('path').attr('fill','none').attr('stroke',window.BookTheme.color('#e4c389')).attr('stroke-width',1.6).attr('d',d3.line().x(d=>x(d.lambda)).y(d=>y(d.flux))(data));
  lines.forEach((l,i)=>{if(l.center<domain[0]||l.center>domain[1])return;svg.append('line').attr('x1',x(l.center)).attr('x2',x(l.center)).attr('y1',m.top+8).attr('y2',h-m.bottom).attr('stroke',l.color).attr('stroke-dasharray','3 5').attr('opacity',.45);svg.append('text').attr('x',x(l.center)).attr('y',i===1?m.top+22:m.top-8).attr('text-anchor',x(l.center)>w-50?'end':i===0?'end':'start').style('fill',l.color).text(l.name);});
  $('line-readouts').replaceChildren();for(const l of lines){const row=document.createElement('div'),title=document.createElement('span'),v=document.createElement('strong'),unit=document.createElement('span');title.textContent=l.name;v.textContent=l.center.toFixed(2);unit.textContent='nm · 真空波长';row.append(title,v,unit);$('line-readouts').append(row);}$('spectrum-note').textContent=`Hα 的观测半高全宽约 ${ha.fwhm.toFixed(2)} nm，包含仪器展宽。${s.zoom?'局部坐标随 Hα 中心移动；注意横轴的绝对波长。':'三条线共享同一红移；并非统一加上相同的波长差。'}`;}
 for(const k of ['redshift','dispersion']){$(k).addEventListener('input',e=>{stop('spectral');state.spectral[k]=+e.target.value;updateSpectrum();});$(k).addEventListener('change',save);}
 $('spectrum-zoom').addEventListener('click',()=>{state.spectral.zoom=!state.spectral.zoom;updateSpectrum();save();});
 $('spectrum-play').addEventListener('click',()=>{if(players.spectral.active){stop('spectral');save();return;}if(state.spectral.redshift>=.5)state.spectral.redshift=0;players.spectral.active=true;players.spectral.last=0;$('spectrum-play').textContent='暂停';requestAnimationFrame(spectralTick);});
 function spectralTick(t){const p=players.spectral;if(!p.active)return;if(!p.last)p.last=t;const dt=t-p.last;if(dt>=60){state.spectral.redshift=Math.min(.5,state.spectral.redshift+Math.min(dt,100)*.00007);p.last=t;updateSpectrum();}if(state.spectral.redshift>=.5){stop('spectral');save();}else requestAnimationFrame(spectralTick);}
 $('spectrum-question').addEventListener('click',()=>tutor(`依据 MBW §2.1.2 pp.29–32，解释红移与线宽的区别。当前合成光谱 z=${state.spectral.redshift.toFixed(4)}、视向速度弥散=${state.spectral.dispersion} km/s、仪器分辨本领 ℛ=1000。真空 Hα 波长为656.461 nm，观测中心为 ${(656.461*(1+state.spectral.redshift)).toFixed(3)} nm。高斯线型与线强比为教学构造。请解释为何不能把 z=0.5 简单当作 v=0.5c，及仪器展宽如何影响速度弥散测量。波长依据 https://classic.sdss.org/dr7/algorithms/linestable.php 。`));

 function drawProfileImage(){const canvas=$('profile-image'),{context:ctx,width:w,height:h}=canvasSetup(canvas);if(!w)return;const sample=document.createElement('canvas'),sw=Math.min(400,Math.round(w)),sh=Math.round(h*sw/w);sample.width=sw;sample.height=sh;const sc=sample.getContext('2d'),im=sc.createImageData(sw,sh),p=state.profile,scale=60/sw;for(let yy=0;yy<sh;yy++)for(let xx=0;xx<sw;xx++){const r=Math.hypot(xx-sw/2,yy-sh/2)*scale,t=1-Math.exp(-Math.pow(P.surfaceDensity(r,p.n,p.re)*80,.7)),k=(yy*sw+xx)*4;im.data[k]=7+238*t;im.data[k+1]=15+216*t;im.data[k+2]=24+180*t;im.data[k+3]=255;}sc.putImageData(im,0,0);ctx.drawImage(sample,0,0,w,h);ctx.beginPath();ctx.arc(w/2,h/2,p.re*p.aperture/60*w,0,2*Math.PI);ctx.lineWidth=1;ctx.strokeStyle=window.BookTheme.color('#e4c389aa');ctx.stroke();ctx.fillStyle=window.BookTheme.color('#b5cebb');ctx.font='11px -apple-system,sans-serif';ctx.fillText(`n = ${p.n}   /   孔径 ${(p.re*p.aperture).toFixed(1)} kpc`,15,22);}
 function updateProfile(){const p=state.profile;for(const[k,id]of Object.entries({n:'profile-n',re:'profile-re',aperture:'profile-aperture'}))$(id).value=p[k];$('profile-n-value').textContent=p.n;$('profile-re-value').textContent=p.re.toFixed(1)+' kpc';$('aperture-value').textContent=p.aperture.toFixed(1)+' Rₑ';$('profile-compare').setAttribute('aria-pressed',String(p.compare));$('profile-compare').textContent=p.compare?'移除 n=1 参照':'叠加 n=1 参照';document.querySelectorAll('[data-profile-n]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.profileN===p.n)));const f=chartFrame('profile-chart'),{svg,w,h,m}=f,x=d3.scaleLinear().domain([0,6]).range([m.left,w-m.right]),y=d3.scaleLog().domain([1e-5,1e3]).range([h-m.bottom,m.top]);axes(f,x,y,'半径 / Rₑ','I(R) / Iₑ · 对数',{log:true});const q=[...new Set([0,...Array.from({length:120},(_,i)=>10**(-6+5*i/119)),...Array.from({length:400},(_,i)=>6*i/399),p.aperture])].sort((a,b)=>a-b);svg.append('defs').append('clipPath').attr('id','profile-clip').append('rect').attr('x',m.left).attr('y',m.top).attr('width',w-m.left-m.right).attr('height',h-m.top-m.bottom);const paths=svg.append('g').attr('clip-path','url(#profile-clip)');const line=n=>d3.line().x(v=>x(v)).y(v=>y(P.profileRatio(v,n)))(q);paths.append('path').attr('d',line(p.n)).attr('fill','none').attr('stroke',window.BookTheme.color('#e4c389')).attr('stroke-width',2);if(p.compare)paths.append('path').attr('data-profile-reference','').attr('d',line(1)).attr('fill','none').attr('stroke',window.BookTheme.color('#7abdc4')).attr('stroke-dasharray','5 4').attr('stroke-width',1.5);paths.append('line').attr('x1',x(p.aperture)).attr('x2',x(p.aperture)).attr('y1',m.top).attr('y2',h-m.bottom).attr('stroke',window.BookTheme.color('#98aeae')).attr('stroke-dasharray','3 4');paths.append('circle').attr('cx',x(p.aperture)).attr('cy',y(P.profileRatio(p.aperture,p.n))).attr('r',4).attr('fill',window.BookTheme.color('#e4c389'));window.BookCharts.setSeries(svg.node(),[{label:'Sérsic 光强剖面',data:q.map(x=>({x,y:P.profileRatio(x,p.n)}))},...(p.compare?[{label:'n=1参照',data:q.map(x=>({x,y:P.profileRatio(x,1)}))}]:[])]);$('profile-result').textContent=`${p.aperture.toFixed(1)} Rₑ 内包含 ${(100*P.enclosed(p.aperture,p.n)).toFixed(1)}% 的总光。剖面包含中心并加密采样，超过纵轴上限的中心亮度在图框外。${p.compare?'青色虚线为 n=1 的归一化剖面。':''}`;drawProfileImage();}
 for(const[k,id]of Object.entries({n:'profile-n',re:'profile-re',aperture:'profile-aperture'})){$(id).addEventListener('input',e=>{state.profile[k]=+e.target.value;updateProfile();});$(id).addEventListener('change',save);}
 document.querySelectorAll('[data-profile-n]').forEach(b=>b.addEventListener('click',()=>{state.profile.n=+b.dataset.profileN;updateProfile();save();}));$('profile-compare').addEventListener('click',()=>{state.profile.compare=!state.profile.compare;updateProfile();save();});
 $('profile-question').addEventListener('click',()=>tutor(`我在学习 MBW pp.42–43 式(2.22)–(2.24)及 pp.49–50 指数盘。当前圆对称 Sérsic 模型 n=${state.profile.n}，Rₑ=${state.profile.re} kpc，bₙ=${P.beta(state.profile.n).toFixed(6)}，孔径=${state.profile.aperture} Rₑ，包围总光比例=${(100*P.enclosed(state.profile.aperture,state.profile.n)).toFixed(2)}%。模型总光度固定且无限延伸，图像只有有限视场。请解释有效半径与尺度长度区别、n 如何改变中心与外翼、为何不能仅由 n 判断形成历史。`));

 const catalogue=P.makeSurvey();let selected=[];
 function updateSurvey(){const s=state.survey;$('survey-limit').value=s.limit;$('survey-mode').value=s.mode;$('survey-distance').value=s.distance;$('survey-distance').disabled=s.mode==='flux';$('limit-value').textContent=s.limit.toFixed(1)+' mag';$('volume-value').textContent=s.distance+' Mpc';selected=P.selectSurvey(catalogue,s.limit,s.mode,s.distance);const count=selected.filter(g=>g.selected).length,threshold=P.limitMagnitude(s.distance,s.limit);$('survey-count').textContent=count;$('survey-readout').textContent=s.mode==='flux'?`通量限制：越远的边界只保留越明亮的星系。当前检测到 ${count} 个。`:`体积限制：d ≤ ${s.distance} Mpc 且 M ≤ ${threshold.toFixed(2)}；保留 ${count} 个，完整性仅针对上述光度范围与理想通量门槛。`;$('survey-hover').textContent='在图中移动指针或轻点一个位置，查看最近的合成星系。';const f=chartFrame('survey-chart'),{svg,w,h,m}=f,x=d3.scaleLinear().domain([10,100]).range([m.left,w-m.right]),y=d3.scaleLinear().domain([-14,-23]).range([h-m.bottom,m.top]);axes(f,x,y,'距离 / Mpc','绝对星等 M');svg.append('defs').append('clipPath').attr('id','survey-clip').append('rect').attr('x',m.left).attr('y',m.top).attr('width',w-m.left-m.right).attr('height',h-m.top-m.bottom);const plot=svg.append('g').attr('clip-path','url(#survey-clip)');
  if(s.mode==='volume')plot.append('rect').attr('data-complete-region','').attr('x',x(10)).attr('y',y(-23)).attr('width',x(s.distance)-x(10)).attr('height',Math.max(0,y(Math.min(-14,threshold))-y(-23))).attr('fill',window.BookTheme.color('#b5cebb')).attr('opacity',.06).attr('stroke',window.BookTheme.color('#b5cebb'));plot.selectAll('circle.galaxy').data(selected).join('circle').attr('class','galaxy').attr('cx',g=>x(g.distance)).attr('cy',g=>y(g.M)).attr('r',g=>g.selected?2:1.3).attr('fill',g=>g.selected?window.BookTheme.color('#e4c389'):g.detected?window.BookTheme.color('#7abdc4'):window.BookTheme.color('#465760')).attr('opacity',g=>g.selected?.78:.45);
  const boundary=Array.from({length:101},(_,i)=>10+.9*i);plot.append('path').attr('data-flux-boundary','').attr('fill','none').attr('stroke',window.BookTheme.color('#e4c389')).attr('stroke-width',1.3).attr('d',d3.line().x(v=>x(v)).y(v=>y(P.limitMagnitude(v,s.limit)))(boundary));if(s.mode==='volume'){plot.append('line').attr('x1',x(s.distance)).attr('x2',x(s.distance)).attr('y1',m.top).attr('y2',h-m.bottom).attr('stroke',window.BookTheme.color('#b5cebb')).attr('stroke-dasharray','4 4');plot.append('line').attr('x1',m.left).attr('x2',x(s.distance)).attr('y1',y(threshold)).attr('y2',y(threshold)).attr('stroke',window.BookTheme.color('#b5cebb')).attr('stroke-dasharray','4 4');}
  const focus=plot.append('circle').attr('r',5).attr('fill','none').attr('stroke',window.BookTheme.color('#e7efed')).attr('display','none');svg.append('rect').attr('x',m.left).attr('y',m.top).attr('width',w-m.left-m.right).attr('height',h-m.top-m.bottom).attr('fill','transparent').on('pointermove',e=>{const pos=d3.pointer(e,f.node);let best=null,dist=Infinity;for(const g of selected){const d=(x(g.distance)-pos[0])**2+(y(g.M)-pos[1])**2;if(d<dist){best=g;dist=d;}}if(best){focus.attr('display',null).attr('cx',x(best.distance)).attr('cy',y(best.M));$('survey-hover').textContent=`合成对象 #${best.id}：${best.distance.toFixed(1)} Mpc，M=${best.M.toFixed(2)}，m=${best.m.toFixed(2)}。${best.selected?'当前入选。':best.detected?'已探测，但不在当前体积限制样本中。':'低于探测通量门槛。'}`;}}).on('click',function(e){this.dispatchEvent(new PointerEvent('pointermove',{clientX:e.clientX,clientY:e.clientY,bubbles:true}));}).on('pointerleave',()=>focus.attr('display','none'));
 }
 for(const[k,id]of Object.entries({limit:'survey-limit',mode:'survey-mode',distance:'survey-distance'})){$(id).addEventListener(k==='mode'?'change':'input',e=>{state.survey[k]=k==='mode'?e.target.value:+e.target.value;updateSurvey();save();});}
 $('survey-question').addEventListener('click',()=>tutor(`依据 MBW §2.4 pp.61–63 分析选择效应。合成母样本1400个，M均匀在[-23,-14]，空间密度均匀、d在[10,100] Mpc，忽略演化和宇宙学。当前m_lim=${state.survey.limit}，模式=${state.survey.mode}，体积距离上限=${state.survey.distance} Mpc，M_lim=${P.limitMagnitude(state.survey.distance,state.survey.limit).toFixed(3)}，入选${selected.filter(g=>g.selected).length}个。请解释为什么通量限制改变光度构成，体积限制的完整性适用于谁，并比较1/Vmax方法的局限。这里的合成样本不是实测光度函数。`));

 C.evidence.forEach((e,i)=>{const b=document.createElement('button');b.textContent=e.title;b.dataset.evidence=i;b.addEventListener('click',()=>{state.evidence=i;showEvidence();save();});$('evidence-menu').append(b);const a=document.createElement('article');a.className='evidence-reading';a.id='section-'+(i+5);const label=document.createElement('span');label.className='small-label';label.textContent=e.section;const h=document.createElement('h3');h.textContent=e.title;a.append(label,h);e.paragraphs.forEach(text=>{const p=document.createElement('p');p.textContent=text;a.append(p);});$('cosmic-reading').append(a);});
 function showEvidence(){const e=C.evidence[state.evidence];for(const k of ['section','title','measurement','inference','caveat'])$('evidence-'+k).textContent=e[k];document.querySelectorAll('[data-evidence]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.evidence===state.evidence)));}
 C.quizzes.forEach(([q,answers,correct,why],i)=>{const a=document.createElement('article');a.className='quiz-item';const h=document.createElement('h3');h.textContent=(i+1)+'. '+q;const options=document.createElement('div');options.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');answers.forEach((text,j)=>{const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{options.querySelectorAll('button').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===b)));feedback.textContent=(j===correct?'正确。':'再想一想。')+why;});options.append(b);});a.append(h,options,feedback);$('quiz').append(a);});
 updatePhoto();updateSpectrum();updateProfile();updateSurvey();showEvidence();stop('photo');stop('spectral');
 let width=0;new ResizeObserver(entries=>{const w=entries[0].contentRect.width;if(Math.abs(w-width)<1)return;width=w;updatePhoto();updateSpectrum();updateProfile();updateSurvey();}).observe($('reading'));
})();
